import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False)
    records = [row for row in reader if row and any(value != "" for value in row)]

    header_index = next((i for i, row in enumerate(records) if len(row) == 4), None)
    if header_index is None:
        header_index = next((i for i, row in enumerate(records) if len(row) >= 3), None)
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = list(records[header_index])
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    rows = []
    for record in records[header_index + 1:]:
        row = list(record)
        if len(row) > len(columns):
            for index in range(len(columns), len(row)):
                columns.append(f"_extra_{index + 1}")
            for prior in rows:
                prior.extend([""] * (len(columns) - len(prior)))
        row.extend([""] * (len(columns) - len(row)))
        rows.append(row)

    return {"columns": columns, "rows": rows}
